import { Fragment, ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { DefaultTFuncReturn, StringMap } from "i18next";
import { LabelKey } from "@/core/labels/i18n";

export type TranslationWithWrappersProps<K extends string | number, T extends Record<K, string>> = {
  label: LabelKey;
  interpolation: T;
  wrappers: Partial<Record<K, (s: string) => ReactNode>>;
};
export function TranslationWithWrappers<
  K extends string | number = string | number,
  T extends Record<K, string> = Record<K, string>,
>({ label, interpolation, wrappers }: TranslationWithWrappersProps<K, T>) {
  const { t } = useTranslation();
  const toKey = (key: string | number) => `{{${key}}}`;

  const splittableReplacements = Object.fromEntries(
    Object.keys(interpolation ?? {}).map((key) => [key, wrappers[key as K] ? toKey(key) : interpolation[key as K]]),
  ) as T;
  const text = t<LabelKey, DefaultTFuncReturn, StringMap, "translation", T, "translation">(
    label,
    splittableReplacements,
  );
  const elements = (Object.entries(wrappers) as Array<[K, TranslationWithWrappersProps<K, T>["wrappers"][K]]>).reduce(
    (nodes, [key, wrapper]) =>
      nodes.flatMap((node, nodeIndex) => {
        if (typeof node !== "string" || !wrapper) return node;
        const parts = node.split(toKey(key));
        return parts.flatMap((part, partIndex) => {
          if (partIndex === 0) return part;
          const fragmentKey = `${key}_${nodeIndex}_${partIndex}`;
          return [<Fragment key={fragmentKey}>{wrapper(interpolation[key as K])}</Fragment>, part];
        });
      }),
    [text as ReactNode],
  );
  return <>{elements}</>;
}
