import { PropsWithChildren, useState } from "react";
import styles from "./summary-list.module.less";
import { AnimatePresence, motion } from "framer-motion";
import Icon from "@/core/components/primitives/icon/icon";
import { isNonEmptyArray } from "@/core/helpers";
import { DisappearingChildren } from "@/core/components/primitives/expand-content/expand-content";

export type Summary = {
  category: string;
  quantity: string;
  sumPrice?: string;
  summaryItems: Array<SummaryItem>;
};

type SummaryListProps = PropsWithChildren<
  {
    preExpanded?: boolean;
    removeChildrenWhenUnexpanded?: boolean;
    ariaLabelsIcon?: {
      whenExpanded: string;
      whenCollapsed: string;
    };
  } & Partial<Summary> & // We want to make summaryItems optional to allow for custom children
    Omit<Summary, "summaryItems">
>;

export type SummaryItem = {
  title: string;
  subtitle?: string;
  price?: string;
};

const SummaryList = ({
  category,
  preExpanded,
  removeChildrenWhenUnexpanded,
  ariaLabelsIcon,
  quantity,
  sumPrice,
  ...items
}: SummaryListProps) => {
  const [isExpanded, setIsExpanded] = useState(preExpanded);

  return (
    <div className={styles.wrapper}>
      <button className={styles.expandButton} onClick={() => setIsExpanded(!isExpanded)}>
        <motion.div
          className={styles.iconWrapper}
          initial={{ rotate: isExpanded ? 180 : 0 }}
          animate={{ rotate: isExpanded ? 180 : 0 }}
          aria-label={
            ariaLabelsIcon ? (isExpanded ? ariaLabelsIcon.whenExpanded : ariaLabelsIcon.whenCollapsed) : undefined
          }
        >
          <Icon name="expand-more" className={styles.expandIcon} />
        </motion.div>
        <span className={styles.category}>{category}</span>
        <div className={styles.quantityPriceSummary}>
          <span className={styles.quantity}>{quantity}</span>
          {sumPrice && <span className={styles.sumPrice}>{sumPrice}</span>}
        </div>
      </button>
      <motion.div
        initial={{ height: isExpanded ? "auto" : 0 }}
        animate={{ height: isExpanded ? "auto" : 0 }}
        transition={{ type: "tween" }}
        className={styles.listWrapper}
      >
        {"summaryItems" in items && isNonEmptyArray(items.summaryItems) && (
          <ul className={styles.list}>
            {items.summaryItems.map((item, index) => {
              return (
                <li key={`${index}-${item.title}`} className={styles.item}>
                  <div className={styles.itemTextWrapper}>
                    <div className={styles.itemTitle}>{item.title}</div>
                    {item.subtitle && <div className={styles.itemSubtitle}>{item.subtitle}</div>}
                  </div>
                  {item.price && <div className={styles.itemPrice}>{item.price}</div>}
                </li>
              );
            })}
          </ul>
        )}
        {removeChildrenWhenUnexpanded ? (
          <AnimatePresence>
            {isExpanded && <DisappearingChildren>{items.children}</DisappearingChildren>}
          </AnimatePresence>
        ) : (
          items.children
        )}
      </motion.div>
    </div>
  );
};

export default SummaryList;
